function hasLowHighMiddle(nums: number[]): boolean {
  let low = Infinity;
  for (let j = 0; j < nums.length; j++) {
    for (let k = j + 1; k < nums.length; k++) {
      if (low < nums[k] && nums[k] < nums[j]) return true;
    }
    low = Math.min(low, nums[j]);
  }
  return false;
}

