function hasLowHighMiddle(nums: number[]): boolean {
  const stack: number[] = [];
  let third = -Infinity; // best middle value with a bigger value to its left
  for (let i = nums.length - 1; i >= 0; i--) {
    if (nums[i] < third) return true;
    while (stack.length && stack[stack.length - 1] < nums[i]) third = stack.pop()!;
    stack.push(nums[i]);
  }
  return false;
}

