    def hasLowHighMiddle(self, nums: List[int]) -> bool:
        stack = []
        third = float("-inf")  # best middle value with a bigger value to its left
        for x in reversed(nums):
            if x < third:
                return True
            while stack and stack[-1] < x:
                third = stack.pop()
            stack.append(x)
        return False

